    (r'annonce', r'\b(?:announcements?|advertisements?)\b', 'listing|listings'),
    (r'\bavis\b', r'\b(?:opinions?|notices?|advices?)\b', 'review|reviews'),
    (r'filleul', r'\b(?:gods?|girls?|godchild(?:ren)?|sponsors?)\b', 'referred friend|referred friends'),
    (r'compétence', r'\b(?:jurisdictions?|competences?|expertise)\b', 'skill|skills'),
    (r'borne', r'\b(?:terminals?|bornes?|stations?)\b', 'kiosk|kiosks'),
    (r'casier', r'\bcases?\b', 'locker|lockers'),
    (r'séquestre', r'\b(?:receiver|receivership)\b', 'escrow|escrow'),
    (r'vœu|voeu', r'\b(?:wanted|want|greeting)\b', 'wish|wishes'),
    (r'iut', r'\b(?:UTE|UTU|UTLE|ITUT|UTA)\b', 'IUT|IUT'),
